import os

def make_icon(filepath, bg_color, inner_content):
    svg = f'''<svg xmlns="http://www.w3.org/2000/svg" width="256" height="256" viewBox="0 0 256 256" fill="none">
  <rect width="256" height="256" rx="60" fill="{bg_color}"/>
{inner_content}
</svg>
'''
    with open(filepath, 'w', encoding='utf-8') as f:
        f.write(svg)

